<?php

declare(strict_types=1);

namespace App\Controllers;

use App\Core\Controller;
use App\Core\Database;
use App\Services\AuditService;
use App\Services\EncryptionService;
use PDO;

final class StaffController extends Controller
{
    private function guard(string $action):void{if(!can('staff.'.$action)){http_response_code(403);view('errors/403',['title'=>'Access denied']);exit;}}
    public function index():void{$this->guard('view');$db=Database::connection();$q=trim($_GET['q']??'');$statement=$db->prepare("SELECT s.*,u.name,u.email,u.phone,u.status user_status,d.name department_name,g.name designation_name FROM staff_profiles s JOIN users u ON u.id=s.user_id LEFT JOIN departments d ON d.id=s.department_id LEFT JOIN designations g ON g.id=s.designation_id WHERE s.deleted_at IS NULL AND (u.name LIKE ? OR u.email LIKE ? OR s.employee_code LIKE ?) ORDER BY u.name");$search='%'.$q.'%';$statement->execute([$search,$search,$search]);$rows=$statement->fetchAll();$this->render('staff/index',compact('rows','q')+['title'=>'Staff Directory']);}
    public function create():void{$this->guard('create');$this->render('staff/form',$this->options()+['record'=>[],'title'=>'Add Staff Member']);}
    public function edit(string $id):void{$this->guard('edit');$q=Database::connection()->prepare('SELECT s.*,u.name,u.email,u.phone,u.status user_status FROM staff_profiles s JOIN users u ON u.id=s.user_id WHERE s.id=? AND s.deleted_at IS NULL');$q->execute([(int)$id]);$record=$q->fetch();if(!$record){http_response_code(404);view('errors/404',['title'=>'Staff member not found']);return;}$this->render('staff/form',$this->options()+compact('record')+['title'=>'Edit Staff Member']);}
    public function store():void
    {
        $this->guard('create');$required=['name','email','phone','employee_code','joining_date','monthly_salary','password'];foreach($required as $f)if(trim($_POST[$f]??'')===''){flash('error','Complete all required staff fields.');$_SESSION['_old']=$_POST;$this->redirect('staff/create');}
        try{$id=Database::transaction(function(PDO $db):int{$db->prepare("INSERT INTO users(branch_id,name,email,phone,password,user_type,status,must_change_password,created_by) VALUES((SELECT id FROM branches ORDER BY id LIMIT 1),?,?,?,?, 'staff','active',1,?)")->execute([trim($_POST['name']),mb_strtolower(trim($_POST['email'])),trim($_POST['phone']),password_hash($_POST['password'],PASSWORD_DEFAULT),auth()['id']]);$userId=(int)$db->lastInsertId();$db->prepare("INSERT INTO user_roles(user_id,role_id) SELECT ?,id FROM roles WHERE slug='staff'")->execute([$userId]);$db->prepare('INSERT INTO staff_profiles(user_id,employee_code,department_id,designation_id,reporting_manager_id,shift_id,emergency_contact,address,joining_date,employment_type,monthly_salary,daily_salary_rate,work_location,bank_name,bank_account_number,ifsc,pan,aadhaar_encrypted,employment_status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$userId,trim($_POST['employee_code']),$_POST['department_id']?:null,$_POST['designation_id']?:null,$_POST['reporting_manager_id']?:null,$_POST['shift_id']?:null,trim($_POST['emergency_contact']??''),trim($_POST['address']??''),$_POST['joining_date'],$_POST['employment_type'],(float)$_POST['monthly_salary'],(float)($_POST['daily_salary_rate']??0),trim($_POST['work_location']??''),trim($_POST['bank_name']??''),trim($_POST['bank_account_number']??''),trim($_POST['ifsc']??''),trim($_POST['pan']??''),EncryptionService::encrypt($_POST['aadhaar']??null),'active']);$staffId=(int)$db->lastInsertId();AuditService::log('created','staff_profiles',$staffId,[],['user_id'=>$userId,'employee_code'=>$_POST['employee_code']]);return $staffId;});flash('success','Staff member and secure login created.');$this->redirect('staff');}catch(\Throwable $e){flash('error',str_contains($e->getMessage(),'Duplicate')?'Email or employee code already exists.':$e->getMessage());$_SESSION['_old']=$_POST;$this->redirect('staff/create');}
    }
    public function update(string $id):void
    {
        $this->guard('edit');$required=['name','email','phone','employee_code','joining_date','monthly_salary'];foreach($required as $f)if(trim($_POST[$f]??'')===''){flash('error','Complete all required staff fields.');$this->redirect('staff/'.$id.'/edit');}
        try{Database::transaction(function(PDO $db)use($id):void{$q=$db->prepare('SELECT * FROM staff_profiles WHERE id=? AND deleted_at IS NULL FOR UPDATE');$q->execute([(int)$id]);$old=$q->fetch();if(!$old)throw new \RuntimeException('Staff profile not found.');$passwordSql='';$params=[trim($_POST['name']),mb_strtolower(trim($_POST['email'])),trim($_POST['phone']),$_POST['user_status']??'active'];if(!empty($_POST['password'])){$passwordSql=',password=?,must_change_password=1';$params[]=password_hash($_POST['password'],PASSWORD_DEFAULT);}$params[]=$old['user_id'];$db->prepare("UPDATE users SET name=?,email=?,phone=?,status=?{$passwordSql} WHERE id=?")->execute($params);$aadhaarSql='';$profileParams=[trim($_POST['employee_code']),$_POST['department_id']?:null,$_POST['designation_id']?:null,$_POST['reporting_manager_id']?:null,$_POST['shift_id']?:null,trim($_POST['emergency_contact']??''),trim($_POST['address']??''),$_POST['joining_date'],$_POST['employment_type'],(float)$_POST['monthly_salary'],(float)($_POST['daily_salary_rate']??0),trim($_POST['work_location']??''),trim($_POST['bank_name']??''),trim($_POST['bank_account_number']??''),trim($_POST['ifsc']??''),trim($_POST['pan']??''),$_POST['employment_status']??'active'];if(trim($_POST['aadhaar']??'')!==''){$aadhaarSql=',aadhaar_encrypted=?';$profileParams[]=EncryptionService::encrypt($_POST['aadhaar']);}$profileParams[]=(int)$id;$db->prepare("UPDATE staff_profiles SET employee_code=?,department_id=?,designation_id=?,reporting_manager_id=?,shift_id=?,emergency_contact=?,address=?,joining_date=?,employment_type=?,monthly_salary=?,daily_salary_rate=?,work_location=?,bank_name=?,bank_account_number=?,ifsc=?,pan=?,employment_status=?{$aadhaarSql} WHERE id=?")->execute($profileParams);AuditService::log('updated','staff_profiles',(int)$id,$old,['employee_code'=>$_POST['employee_code'],'monthly_salary'=>$_POST['monthly_salary']]);});flash('success','Staff profile updated.');$this->redirect('staff');}catch(\Throwable $e){flash('error',str_contains($e->getMessage(),'Duplicate')?'Email or employee code already exists.':$e->getMessage());$this->redirect('staff/'.$id.'/edit');}
    }
    private function options():array{$db=Database::connection();return ['departments'=>$db->query('SELECT id,name FROM departments WHERE is_active=1 ORDER BY name')->fetchAll(),'designations'=>$db->query('SELECT id,name FROM designations WHERE is_active=1 ORDER BY name')->fetchAll(),'shifts'=>$db->query('SELECT id,name FROM shifts WHERE is_active=1 ORDER BY name')->fetchAll(),'managers'=>$db->query("SELECT s.id,u.name FROM staff_profiles s JOIN users u ON u.id=s.user_id WHERE s.employment_status='active' ORDER BY u.name")->fetchAll()];}
}
